insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Cosa serve per prenotare un tavolo?', $qml1hgi$["cosa serve per prenotare","che dati servono per prenotare","cosa devo dire per prenotare","come si prenota un tavolo"]$qml1hgi$::jsonb, 'Per prenotare servono in genere il numero di persone, il giorno, pranzo o cena (o l''orario) e un nome. È utile indicare subito anche eventuali allergie, seggioloni o altre esigenze particolari.', $qbfsu1i${}$qbfsu1i$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Conviene prenotare nel weekend?', $qwbede0$["serve prenotare nel weekend","bisogna prenotare il sabato sera","conviene prenotare","meglio prenotare"]$qwbede0$::jsonb, 'In genere nei fine settimana, nei giorni festivi e per gruppi è consigliabile prenotare con anticipo; le regole di questo locale vanno però verificate con il locale stesso.', $qsur22f${}$qsur22f$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Cosa sono i coperti?', $qlhppwb$["cosa significa coperti","cosa sono i coperti","che vuol dire coperti","cosa vuol dire coperto"]$qlhppwb$::jsonb, 'I "coperti" sono i posti a sedere, cioè il numero di persone sedute al tavolo; il "coperto" è invece la voce che alcuni locali applicano per ciascun commensale. Se previsto, deve essere indicato nel menu.', $q2414t3${}$q2414t3$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Cosa succede se sono in ritardo?', $qbmnn47$["faccio ritardo cosa succede","se arrivo in ritardo il tavolo resta","quanto ritardo posso fare","se facciamo tardi"]$qbmnn47$::jsonb, 'In caso di ritardo è importante avvisare il locale il prima possibile: il tempo per cui il tavolo viene tenuto è stabilito dal locale.', $qxbs9hy${}$qxbs9hy$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Cos''è una caparra?', $qnuvr9r$["cosa e la caparra","a cosa serve la caparra","perche chiedono la caparra","cos e la caparra"]$qnuvr9r$::jsonb, 'Alcuni locali chiedono una caparra o una garanzia (per esempio per gruppi o in date molto richieste). Se prevista, importo e condizioni sono stabiliti dal locale.', $ql281vo${}$ql281vo$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prenotazioni', 'Si prenota con i bambini piccoli?', $q03ox1l$["prenotare con bambini","devo contare i bambini nella prenotazione","i bambini si contano nei coperti","bambini piccoli prenotazione"]$q03ox1l$::jsonb, 'Conviene indicare anche i bambini nel numero di persone e dire se serve un seggiolone, così il locale può organizzare il tavolo.', $q9f2ksr${}$q9f2ksr$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_locale', 'Come richiedo un seggiolone?', $qc278i2$["serve il seggiolone","come chiedo il seggiolone","si puo avere un seggiolone","seggiolone per bambini prenotazione"]$qc278i2$::jsonb, 'Se serve un seggiolone conviene segnalarlo già in fase di prenotazione, così il locale può prepararsi. La disponibilità dipende dal locale.', $qgojmws${}$qgojmws$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_locale', 'Posso portare il cane al ristorante?', $qtp15tm$["si possono portare i cani al ristorante","i cani sono ammessi nei ristoranti","posso entrare con il cane","animali ammessi"]$qtp15tm$::jsonb, 'L''ammissione degli animali dipende dalle scelte di ogni locale: alcuni li accolgono, altri no, o solo in alcune aree. Conviene segnalarlo in fase di prenotazione.', $q98hnzm${}$q98hnzm$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_locale', 'Come segnalo un''esigenza di accessibilità?', $qmu2x3i$["sedia a rotelle al ristorante","devo segnalare la sedia a rotelle","accessibilita ristorante disabili","come prenotare con la sedia a rotelle"]$qmu2x3i$::jsonb, 'Se qualcuno si muove in sedia a rotelle o con difficoltà motorie conviene segnalarlo in prenotazione: il locale potrà indicare l''accesso e il tavolo più adatti.', $q5u0a4s${}$q5u0a4s$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_locale', 'Meglio un tavolo all''aperto o dentro?', $qxvxgwh$["tavolo fuori o dentro","posso scegliere il tavolo","si puo scegliere dove sedersi","posso chiedere un tavolo in terrazza"]$qxvxgwh$::jsonb, 'Si può esprimere una preferenza (interno, esterno, terrazza) in fase di prenotazione, ma l''assegnazione dipende dalla disponibilità e dal meteo, quindi non è garantita.', $quifqm8${}$quifqm8$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_allergie', 'Come comunico allergie o intolleranze?', $q1mvsp6$["devo dire le allergie","come segnalo un allergia","ho un allergia cosa devo fare","segnalare intolleranze al ristorante"]$q1mvsp6$::jsonb, 'Allergie e intolleranze vanno comunicate in anticipo e, soprattutto, confermate direttamente con il personale di sala o cucina, che conosce ingredienti e preparazioni. In chat non si può dare conferma dell''assenza di allergeni.', $qdim4mz${}$qdim4mz$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_allergie', 'Per i celiaci cosa conviene fare?', $qlgqrbw$["sono celiaco cosa devo fare","ristorante per celiaci","come mangiare senza glutine al ristorante","cosa devo dire se sono celiaco"]$qlgqrbw$::jsonb, 'Chi è celiaco dovrebbe segnalarlo al momento della prenotazione e chiedere conferma al personale su opzioni e modalità di preparazione. L''assistente non può assicurare l''assenza di glutine o di contaminazioni.', $q81nurc${}$q81nurc$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_allergie', 'Il locale deve dichiarare gli allergeni?', $qj26sg8$["obbligo allergeni ristorante","i ristoranti devono indicare gli allergeni","lista allergeni obbligatoria","devono dirmi gli allergeni"]$qj26sg8$::jsonb, 'In Italia e nell''Unione Europea i locali sono tenuti a poter fornire ai clienti l''informazione sugli allergeni presenti nei piatti. Per un piatto specifico conviene chiedere al personale.', $qv8w0cv${}$qv8w0cv$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_menu', 'Cos''è un menu degustazione?', $qh8ewwk$["cosa e il menu degustazione","come funziona il menu degustazione","menu degustazione cosa include","cos e un menu degustazione"]$qh8ewwk$::jsonb, 'Il menu degustazione è un percorso di più portate scelte dalla cucina, spesso in porzioni ridotte. Composizione e condizioni (anche l''eventuale prenotazione anticipata) le stabilisce il locale.', $qxufrho${}$qxufrho$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_menu', 'Che differenza c''è tra vegetariano e vegano?', $qihdiel$["differenza vegetariano vegano","vegetariano o vegano cosa cambia","cosa significa vegano","cosa vuol dire vegetariano"]$qihdiel$::jsonb, 'In genere vegetariano significa senza carne e pesce, mentre vegano esclude anche tutti i prodotti di origine animale, come uova, latte e formaggi. Per i dettagli sui piatti del locale conviene verificare con il personale.', $qa4w7f8${}$qa4w7f8$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_menu', 'Il menu cambia?', $q74ui8i$["il menu cambia con le stagioni","il menu e sempre uguale","piatto del giorno cambia","i piatti cambiano"]$q74ui8i$::jsonb, 'In molti locali menu e piatti del giorno cambiano con le stagioni e la disponibilità degli ingredienti: per quelli attuali fa fede il menu del locale.', $qvgf1ez${}$qvgf1ez$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'richiesta_evento', 'Come si organizza una cena di gruppo o un evento?', $q3xpyjt$["organizzare una cena di gruppo","come organizzo una festa al ristorante","cosa serve per un evento","cena aziendale cosa serve"]$q3xpyjt$::jsonb, 'Per eventi e gruppi il locale di solito valuta disponibilità, sala e menu dedicato. Servono data, numero di persone, occasione e se possibile un''idea di budget; poi il locale prepara una proposta.', $q2td5bx${}$q2td5bx$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'richiesta_evento', 'Posso portare una torta?', $q7h0hvc$["posso portare la torta","si puo portare la torta di compleanno","torta da fuori","portare dolci da casa"]$q7h0hvc$::jsonb, 'Alcuni locali accettano torte o dolci portati dai clienti, altri no o con condizioni. Conviene chiederlo al locale quando si organizza la festa.', $qymid86${}$qymid86$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_asporto_consegna', 'Che differenza c''è tra asporto e consegna a domicilio?', $qh5ire6$["asporto cosa significa","differenza asporto consegna","take away cosa vuol dire","cos e l asporto"]$qh5ire6$::jsonb, 'L''asporto (take away) significa ritirare il cibo di persona al locale; la consegna a domicilio è invece portata a casa dal locale o da una piattaforma. Il servizio disponibile e le condizioni dipendono dal locale.', $qmbndj3${}$qmbndj3$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_pagamenti', 'Si può dividere il conto?', $q2r9rwd$["conto alla romana","si puo fare il conto separato","dividere il conto al ristorante","conti separati"]$q2r9rwd$::jsonb, 'La possibilità di dividere il conto o fare conti separati dipende dal locale, conviene segnalarlo in anticipo.', $qmnm9ui${}$qmnm9ui$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_pagamenti', 'Si accettano i buoni pasto?', $qjt84e2$["ticket restaurant accettati","buoni pasto ristorante","accettano i buoni pasto","si possono usare i ticket"]$qjt84e2$::jsonb, 'L''accettazione dei buoni pasto e dei diversi metodi di pagamento varia da locale a locale: va verificata con il locale.', $qp0joh5${}$qp0joh5$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_prezzi', 'Perché c''è il coperto?', $qftbp9b$["cos e il coperto","a cosa serve il coperto","il coperto e obbligatorio","coperto cosa comprende"]$qftbp9b$::jsonb, 'Il coperto è una voce che alcuni locali applicano per ogni commensale (servizio di tavola, pane e simili). Se previsto, deve essere indicato nel menu; importo e cosa comprende li stabilisce il locale.', $qmo18p2${}$qmo18p2$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_posizione', 'Come arrivo se non conosco la zona?', $qiukmyh$["come trovo il ristorante","come si raggiunge il locale","come arrivare al ristorante","posso farmi mandare la posizione"]$qiukmyh$::jsonb, 'Posizione, indicazioni e parcheggio sono quelli indicati dal locale: se non li trovi ti conviene chiederli al locale o guardare la sua scheda online.', $q803d50${}$q803d50$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('ristorante', 1, 'production', 'info_orari', 'Cosa vuol dire orario della cucina?', $qrd0sxk$["orario della cucina cosa significa","a che ora chiude la cucina","orario cucina e orario locale","la cucina chiude prima del locale"]$qrd0sxk$::jsonb, 'In molti locali l''orario in cui la cucina accetta le ordinazioni è diverso dall''orario di apertura. Gli orari esatti sono quelli indicati dal locale.', $q3sj85f${}$q3sj85f$::jsonb);
